window.EffectTools=(()=>{
 let taps=[];
 function controls(b){const d=PatchRig.definition(b.key);if(!d?.presets)return '';const v=state.scenes[state.scene][b.id];return `<div class="effect-tools"><label>Pedal preset <select id="effect-preset"><option value="">Choose a sound…</option>${d.presets.map((p,i)=>`<option value="${i}">${escapeHTML(p.name)}</option>`).join('')}</select></label>${d.sync?`<label>Time <select id="effect-sync">${['Free','1/16','1/8','Dotted 1/8','1/4','Dotted 1/4','1/2','Whole'].map((n,i)=>`<option value="${i}" ${(v.sync||0)===i?'selected':''}>${n}</option>`).join('')}</select></label><label>Tempo <input id="effect-tempo" type="number" min="40" max="240" value="${state.tempo}"> BPM</label><button id="effect-tap">Tap tempo</button>`:''}<small>${escapeHTML(d.engine)} · preset applies to this scene${v.sync?" · synced time limited to 2 s":""}</small></div>`;}
 document.addEventListener('change',e=>{if(!['effect-preset','effect-sync','effect-tempo'].includes(e.target.id))return;const b=state.blocks.find(b=>b.id===selected);if(!b)return;const d=PatchRig.definition(b.key),v=state.scenes[state.scene][b.id];if(e.target.id==='effect-preset'&&e.target.value==='')return;checkpoint();if(e.target.id==='effect-preset'){v.values=[...d.presets[Number(e.target.value)].values];v.sync=0;}if(e.target.id==='effect-sync')v.sync=Number(e.target.value);if(e.target.id==='effect-tempo')state.tempo=Math.max(40,Math.min(240,Math.round(Number(e.target.value)||112)));render();});
 document.addEventListener('click',e=>{if(!e.target.closest('#effect-tap'))return;const now=performance.now();if(taps.length&&now-taps.at(-1)>1800)taps=[];taps.push(now);taps=taps.slice(-5);if(taps.length>1){const bpm=Math.round(60000*(taps.length-1)/(now-taps[0]));checkpoint();state.tempo=Math.max(40,Math.min(240,bpm));render();}});function faceState(d,v){if(!d.sync||!v.sync)return v;const values=[...v.values];values[0]=Math.round(Math.min(2000,60000/state.tempo*[0,.25,.5,.75,1,1.5,2,4][v.sync]));if(d.key==="fx-SurgeDelay")values[1]=values[0];return {...v,values};}return {controls,faceState};
})();

